def arrange_grades(students):
    """
    Determine if students can be arranged in rows where each student
    is strictly taller than the corresponding student in the row in front.
    """
    if not students or len(students) == 0:
        return True

    if len(students) == 1:
        return True

    num_grades = len(students)
    students_per_grade = len(students[0])

    # Check if all grades have the same number of students
    if not all(len(grade) == students_per_grade for grade in students):
        return False

    # Try to find a valid permutation for each grade
    from itertools import permutations

    # Generate all possible permutations for each grade
    all_permutations = []
    for grade in students:
        all_permutations.append(list(permutations(grade)))

    # Recursively try to find a valid arrangement
    def is_valid_arrangement(grade_idx, current_arrangement):
        if grade_idx == num_grades:
            return True

        # Try each permutation for the current grade
        for perm in all_permutations[grade_idx]:
            # Check if this permutation is valid with the previous grade
            if grade_idx == 0:
                # First grade, any permutation is valid
                current_arrangement.append(perm)
                if is_valid_arrangement(grade_idx + 1, current_arrangement):
                    return True
                current_arrangement.pop()
            else:
                # Check if each student is strictly taller than the previous grade
                prev_grade = current_arrangement[grade_idx - 1]
                valid = True
                for i in range(students_per_grade):
                    if perm[i] <= prev_grade[i]:
                        valid = False
                        break

                if valid:
                    current_arrangement.append(perm)
                    if is_valid_arrangement(grade_idx + 1, current_arrangement):
                        return True
                    current_arrangement.pop()

        return False

    return is_valid_arrangement(0, [])
